import re

def split_fields(line):
    def unquote_field(field):
        if field[0] == field[-1] == '"':
            field = field[1:-1]
            field = re.sub(r'""', '"', field)
        return field

    fields = []
    current_field = ''
    in_quotes = False

    for char in line:
        if char == '"':
            if in_quotes:
                if len(current_field) > 0 and current_field[-1] == '"':
                    current_field = current_field[:-1] + '"'
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',' and not in_quotes:
            fields.append(unquote_field(current_field))
            current_field = ''
        else:
            current_field += char

    fields.append(unquote_field(current_field))
    return fields
