def split_fields(line):
    import itertools, re

    def _it(characters):
        while True:
            char = next(characters, None)
            if char is None: return
            yield char

    def _scan(characters):
        state, buffer = 'normal', []
        chars = _it(characters)
        try:
            while True:
                char = next(chars)
                if state == 'normal':
                    if char == '"':
                        state = 'quoted'
                    elif char == ',':
                        yield ''.join(buffer)
                        buffer = []
                    else:
                        buffer.append(char)
                elif state == 'quoted':
                    if char == '"':
                        state = 'escaped'
                    else:
                        buffer.append(char)
                elif state == 'escaped':
                    if char == '"':
                        buffer.append('"')
                        state = 'quoted'
                    else:
                        buffer.append(char)
                        state = 'normal'
        except StopIteration:
            if state == 'quoted':
                raise ValueError('unterminated quoted field')
            yield ''.join(buffer)

    return list(_scan(line))
```

