def split_fields(line):
    # Helper function to unescape doubled quotes
    def unescape_doubles(s):
        return s.replace('""', '"')

    # Regular expression to find fields
    field_re = re.compile(r'"([^"]*)"|([^,]+)')

    # Find all matches in the line
    matches = field_re.findall(line)
    fields = []

    for match in matches:
        # If the match is a quoted field, unescape and add it to the list
        if len(match[0]) > 0:
            fields.append(unescape_doubles(match[0]))
        # If the match is an unquoted field, add it to the list
        else:
            fields.append(match[1])

    return fields
