    import re
    result = []
    field = ""
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if char == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    field += char
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                in_quotes = True
                i += 1
        elif char == ',' and not in_quotes:
            result.append(field)
            field = ""
            i += 1
        else:
            field += char
            i += 1
    result.append(field)
    return result
