import re

def split_fields(line):
    # Regular expression to match quoted fields and unquoted fields
    pattern = re.compile(r'"([^"]*)"|([^,]+)')

    # Function to replace doubled double quotes with a single double quote
    def replace_doubled_quotes(match):
        if match.group(1):
            return match.group(1).replace('""', '"')
        else:
            return match.group(2)

    # Split the line using the pattern
    fields = pattern.findall(line)

    # Join the groups and replace doubled double quotes
    fields = [replace_doubled_quotes(match) for match in fields]

    # Remove empty strings that may have been produced by trailing commas
    fields = [field for field in fields if field]

    return fields
```

